                        this::publishSinglePage,
                        builder -> builder.operationId("PublishSinglePage")
                                .description("Publish a single page. By default, the request waits until the release "
                                        + "snapshot is available.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the single page to publish.")
                                        .in(ParameterIn.PATH)
                                        .required(true)
                                        .implementation(String.class))
                                .parameter(parameterBuilder()
                                        .name("async")
                                        .description("Whether to return immediately after marking the single page for "
                                                + "publishing.")
                                        .in(ParameterIn.QUERY)
                                        .implementation(Boolean.class)
                                        .required(false))
                                .response(responseBuilder().implementation(SinglePage.class)))
                .DELETE(
                        "singlepages/{name}/content",
                        this::deleteContent,
                        builder -> builder.operationId("deleteSinglePageContent")
                                .description("Delete a content snapshot from a single page and return the deleted "
                                        + "content.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the single page.")
                                        .in(ParameterIn.PATH)
                                        .required(true)
                                        .implementation(String.class))
                                .parameter(parameterBuilder()
                                        .name("snapshotName")
                                        .description("Content snapshot metadata.name to delete.")
                                        .in(ParameterIn.QUERY)
                                        .required(true)
                                        .implementation(String.class))
                                .response(responseBuilder().implementation(ContentWrapper.class)))
                .build();
    }

    private Mono<ServerResponse> deleteContent(ServerRequest request) {
        final var postName = request.pathVariable("name");
        final var snapshotName = request.queryParam("snapshotName").orElseThrow();
        return singlePageService
                .deleteContent(postName, snapshotName)
                .flatMap(content -> ServerResponse.ok().bodyValue(content));
    }

    private Mono<ServerResponse> revertToSpecifiedSnapshot(ServerRequest request) {
        final var postName = request.pathVariable("name");
        return request.bodyToMono(RevertSnapshotParam.class)
                .switchIfEmpty(Mono.error(new ServerWebInputException("Required request body is missing.")))
                .flatMap(param -> singlePageService.revertToSpecifiedSnapshot(postName, param.snapshotName))
                .flatMap(page -> ServerResponse.ok().bodyValue(page));
    }

    /**
     * Request body for restoring single page content from a snapshot.
     *
     * @param snapshotName snapshot {@code metadata.name} to restore as the single page's head content
     */
    @Schema(name = "RevertSnapshotForSingleParam")
    record RevertSnapshotParam(
            @Schema(requiredMode = Schema.RequiredMode.REQUIRED, minLength = 1)
            String snapshotName) {}

    private Mono<ServerResponse> fetchContent(ServerRequest request) {
        final var snapshotName = request.queryParam("snapshotName").orElseThrow();
        return client.fetch(SinglePage.class, request.pathVariable("name"))
                .flatMap(page -> {
                    var baseSnapshot = page.getSpec().getBaseSnapshot();
                    return singlePageService.getContent(snapshotName, baseSnapshot);
                })
                .flatMap(content -> ServerResponse.ok().bodyValue(content));
    }

    private Mono<ServerResponse> listSnapshots(ServerRequest request) {
        final var name = request.pathVariable("name");
        var resultFlux = singlePageService.listSnapshots(name);
        return ServerResponse.ok().body(resultFlux, ListedSnapshotDto.class);
    }

    private Mono<ServerResponse> fetchReleaseContent(ServerRequest request) {
        final var name = request.pathVariable("name");
        return singlePageService
                .getReleaseContent(name)
                .flatMap(content -> ServerResponse.ok().bodyValue(content));
    }

    private Mono<ServerResponse> fetchHeadContent(ServerRequest request) {
        String name = request.pathVariable("name");
        return singlePageService
                .getHeadContent(name)
                .flatMap(content -> ServerResponse.ok().bodyValue(content));
    }

    Mono<ServerResponse> draftSinglePage(ServerRequest request) {
        return request.bodyToMono(SinglePageRequest.class)
                .flatMap(singlePageService::draft)
                .flatMap(singlePage -> ServerResponse.ok().bodyValue(singlePage));
    }

    Mono<ServerResponse> updateContent(ServerRequest request) {
        String pageName = request.pathVariable("name");
        return request.bodyToMono(ContentUpdateParam.class)
                .flatMap(content -> Mono.defer(() -> client.fetch(SinglePage.class, pageName)
                                .flatMap(page -> {
                                    SinglePageRequest pageRequest = new SinglePageRequest(page, content);
                                    return singlePageService.update(pageRequest);
                                }))
                        .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
                                .filter(throwable -> throwable instanceof OptimisticLockingFailureException)))
                .flatMap(post -> ServerResponse.ok().bodyValue(post));
    }

    Mono<ServerResponse> updateSinglePage(ServerRequest request) {
        return request.bodyToMono(SinglePageRequest.class)
                .flatMap(singlePageService::update)
                .flatMap(page -> ServerResponse.ok().bodyValue(page));
    }

    Mono<ServerResponse> publishSinglePage(ServerRequest request) {
        String name = request.pathVariable("name");
        boolean asyncPublish =
                request.queryParam("async").map(Boolean::parseBoolean).orElse(false);
        return Mono.defer(() -> client.get(SinglePage.class, name).flatMap(singlePage -> {
                    SinglePage.SinglePageSpec spec = singlePage.getSpec();
                    spec.setPublish(true);
                    if (spec.getHeadSnapshot() == null) {
                        spec.setHeadSnapshot(spec.getBaseSnapshot());
                    }
                    spec.setReleaseSnapshot(spec.getHeadSnapshot());
                    return client.update(singlePage);
                }))
                .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
                        .filter(OptimisticLockingFailureException.class::isInstance))
                .flatMap(post -> {
                    if (asyncPublish) {
                        return Mono.just(post);
                    }
                    return client.fetch(SinglePage.class, name)
                            .flatMap(latest -> {
                                var latestReleasedSnapshotName =
                                        MetadataUtil.nullSafeAnnotations(latest).get(Post.LAST_RELEASED_SNAPSHOT_ANNO);
                                if (!StringUtils.equals(
                                        latestReleasedSnapshotName,
                                        latest.getSpec().getReleaseSnapshot())) {
                                    return Mono.error(new IllegalStateException(
                                            "SinglePage publishing status is not as expected"));
                                }
                                return Mono.just(latest);
                            })
                            .retryWhen(Retry.fixedDelay(10, Duration.ofMillis(100))
                                    .filter(IllegalStateException.class::isInstance))
                            .doOnError(IllegalStateException.class, err -> {
                                log.error("Failed to publish single page [{}]", name, err);
                                throw new IllegalStateException("Publishing wait timeout.");
                            });
                })
                .flatMap(page -> ServerResponse.ok().bodyValue(page));
    }

    Mono<ServerResponse> listSinglePage(ServerRequest request) {
        var listRequest = new SinglePageQuery(request);
        return singlePageService
                .list(listRequest)
                .flatMap(listedPages -> ServerResponse.ok().bodyValue(listedPages));
    }
}

package run.halo.app.content;

import java.security.Principal;
import java.time.Duration;
import java.time.Instant;
import java.util.UUID;
import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.jspecify.annotations.Nullable;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.data.domain.Sort;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.security.core.context.SecurityContext;
import org.springframework.util.Assert;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import reactor.util.retry.Retry;
import run.halo.app.core.extension.content.Snapshot;
import run.halo.app.extension.ListOptions;
import run.halo.app.extension.MetadataUtil;
import run.halo.app.extension.ReactiveExtensionClient;
import run.halo.app.extension.Ref;
import run.halo.app.extension.index.query.Queries;
import run.halo.app.extension.router.selector.FieldSelector;

/**
 * Abstract Service for {@link Snapshot}.
 *
 * @author guqing
 * @since 2.0.0
 */
@Slf4j
@AllArgsConstructor
public abstract class AbstractContentService {

    private final ReactiveExtensionClient client;

    public Mono<ContentWrapper> getContent(String snapshotName, String baseSnapshotName) {
        if (StringUtils.isBlank(snapshotName) || StringUtils.isBlank(baseSnapshotName)) {
            return Mono.empty();
        }
        // TODO: refactor this method to use client.get instead of fetch but please be careful
        return client.fetch(Snapshot.class, baseSnapshotName)
                .doOnNext(this::checkBaseSnapshot)
                .flatMap(baseSnapshot -> {
                    if (StringUtils.equals(snapshotName, baseSnapshotName)) {
                        var contentWrapper = ContentWrapper.patchSnapshot(baseSnapshot, baseSnapshot);
                        return Mono.just(contentWrapper);
                    }
                    return client.fetch(Snapshot.class, snapshotName)
                            .map(snapshot -> ContentWrapper.patchSnapshot(snapshot, baseSnapshot));
                })
                .switchIfEmpty(Mono.defer(() -> {
                    log.error(
                            "The content snapshot [{}] or base snapshot [{}] not found.",
                            snapshotName,
                            baseSnapshotName);
                    return Mono.empty();
                }));
    }

    protected void checkBaseSnapshot(Snapshot snapshot) {
        Assert.notNull(snapshot, "The snapshot must not be null.");
        if (!Snapshot.isBaseSnapshot(snapshot)) {
            throw new IllegalArgumentException(String.format(
                    "The snapshot [%s] is not a base snapshot.",
                    snapshot.getMetadata().getName()));
        }
    }

    protected Mono<ContentWrapper> draftContent(
            @Nullable String baseSnapshotName, ContentRequest contentRequest, @Nullable String parentSnapshotName) {
        return create(baseSnapshotName, contentRequest, parentSnapshotName).flatMap(head -> {
            String baseSnapshotNameToUse = StringUtils.defaultIfBlank(
                    baseSnapshotName, head.getMetadata().getName());
            return restoredContent(baseSnapshotNameToUse, head);
        });
    }

    protected Mono<ContentWrapper> draftContent(String baseSnapshotName, ContentRequest content) {
        return this.draftContent(baseSnapshotName, content, content.headSnapshotName());
    }

    private Mono<Snapshot> create(
            @Nullable String baseSnapshotName, ContentRequest contentRequest, @Nullable String parentSnapshotName) {
        Snapshot snapshot = contentRequest.toSnapshot();
        snapshot.getMetadata().setName(UUID.randomUUID().toString());
        snapshot.getSpec().setParentSnapshotName(parentSnapshotName);

        return client.fetch(Snapshot.class, baseSnapshotName)
                .doOnNext(this::checkBaseSnapshot)
                .defaultIfEmpty(snapshot)
                .map(baseSnapshot -> determineRawAndContentPatch(snapshot, baseSnapshot, contentRequest))
                .flatMap(source -> getContextUsername()
                        .map(username -> {
                            Snapshot.addContributor(source, username);
                            source.getSpec().setOwner(username);
                            return source;
                        }))
                .flatMap(client::create);
    }

    protected Mono<ContentWrapper> updateContent(String baseSnapshotName, ContentRequest contentRequest) {
        Assert.notNull(contentRequest, "The contentRequest must not be null");
        Assert.notNull(baseSnapshotName, "The baseSnapshotName must not be null");
        Assert.notNull(contentRequest.headSnapshotName(), "The headSnapshotName must not be null");
        return Mono.defer(() -> client.fetch(Snapshot.class, contentRequest.headSnapshotName())
                        .flatMap(headSnapshot -> {
                            var oldVersion = contentRequest.version();
                            var version = headSnapshot.getMetadata().getVersion();
                            if (hasConflict(oldVersion, version)) {
                                // draft a new snapshot as the head snapshot
                                return create(baseSnapshotName, contentRequest, contentRequest.headSnapshotName());
                            }
                            return Mono.just(headSnapshot);
                        })
                        .flatMap(headSnapshot -> client.fetch(Snapshot.class, baseSnapshotName)
                                .map(baseSnapshot ->
                                        determineRawAndContentPatch(headSnapshot, baseSnapshot, contentRequest)))
                        .flatMap(headSnapshot -> getContextUsername()
                                .map(username -> {
                                    Snapshot.addContributor(headSnapshot, username);
                                    return headSnapshot;
                                }))
                        .flatMap(client::update))
                .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
                        .filter(throwable -> throwable instanceof OptimisticLockingFailureException))
                .flatMap(head -> restoredContent(baseSnapshotName, head));
    }

    protected Flux<Snapshot> listSnapshotsBy(Ref ref) {
        var snapshotListOptions = new ListOptions();
        var query = Queries.isNull("metadata.deletionTimestamp")
                .and(Queries.equal("spec.subjectRef", Snapshot.toSubjectRefKey(ref)));
        snapshotListOptions.setFieldSelector(FieldSelector.of(query));
        var sort = Sort.by("metadata.creationTimestamp", "metadata.name").descending();
        return client.listAll(Snapshot.class, snapshotListOptions, sort);
    }

    boolean hasConflict(Long oldVersion, Long newVersion) {
        return oldVersion != null && !newVersion.equals(oldVersion);
    }

    protected Mono<ContentWrapper> restoredContent(String baseSnapshotName, Snapshot headSnapshot) {
        return client.fetch(Snapshot.class, baseSnapshotName)
                .doOnNext(this::checkBaseSnapshot)
                .map(baseSnapshot -> ContentWrapper.patchSnapshot(headSnapshot, baseSnapshot));
    }

    protected Snapshot determineRawAndContentPatch(
            Snapshot snapshotToUse, Snapshot baseSnapshot, ContentRequest contentRequest) {
        Assert.notNull(baseSnapshot, "The baseSnapshot must not be null.");
        Assert.notNull(contentRequest, "The contentRequest must not be null.");
        Assert.notNull(snapshotToUse, "The snapshotToUse not be null.");
        String originalRaw = baseSnapshot.getSpec().getRawPatch();
        String originalContent = baseSnapshot.getSpec().getContentPatch();
        String baseSnapshotName = baseSnapshot.getMetadata().getName();

        snapshotToUse.getSpec().setLastModifyTime(Instant.now());
        // it is the v1 snapshot, set the content directly
        if (StringUtils.equals(baseSnapshotName, snapshotToUse.getMetadata().getName())) {
            snapshotToUse.getSpec().setRawPatch(contentRequest.raw());
            snapshotToUse.getSpec().setContentPatch(contentRequest.content());
            MetadataUtil.nullSafeAnnotations(snapshotToUse).put(Snapshot.KEEP_RAW_ANNO, Boolean.TRUE.toString());
        } else {
            // otherwise diff a patch based on the v1 snapshot
            String revisedRaw = contentRequest.rawPatchFrom(originalRaw);
            String revisedContent = contentRequest.contentPatchFrom(originalContent);
            snapshotToUse.getSpec().setRawPatch(revisedRaw);
            snapshotToUse.getSpec().setContentPatch(revisedContent);
        }
        return snapshotToUse;
    }

    protected Mono<String> getContextUsername() {
        return ReactiveSecurityContextHolder.getContext()
                .map(SecurityContext::getAuthentication)
                .map(Principal::getName);
    }
}

